<?php require __DIR__.'/bootstrap.php';$p=db();$d=body();switch(method()){case'GET':respond($p->query('SELECT * FROM case_entities ORDER BY active DESC,relevance_weight DESC,name')->fetchAll());case'POST':requireFields($d,['name','type']);$n=clean($d['name']);$p->prepare('INSERT INTO case_entities(name,normalized_name,type,relevance_weight,active,notes) VALUES(?,?,?,?,?,?)')->execute([$n,mb_strtolower(iconv('UTF-8','ASCII//TRANSLIT',$n)?:$n),clean($d['type']),(int)($d['relevance_weight']??20),(int)($d['active']??1),clean($d['notes']??'')]);respond(['id'=>insertedId($p,'case_entities')],201);case'PUT':requireFields($d,['id','name']);$n=clean($d['name']);$p->prepare('UPDATE case_entities SET name=?,normalized_name=?,type=?,relevance_weight=?,active=?,notes=? WHERE id=?')->execute([$n,mb_strtolower(iconv('UTF-8','ASCII//TRANSLIT',$n)?:$n),clean($d['type']),(int)$d['relevance_weight'],(int)$d['active'],clean($d['notes']??''),(int)$d['id']]);respond(['updated'=>true]);case'DELETE':$p->prepare('DELETE FROM case_entities WHERE id=?')->execute([(int)$d['id']]);respond(['deleted'=>true]);default:fail('Método não permitido',405);}
